// --- what slicers write -----------------------------------------------------------

// OrcaSlicer's header block, as it appears at the top of a file.
const orcaHeader = `; HEADER_BLOCK_START
; generated by OrcaSlicer 2.1.1 on 2026-10-03 at 14:02:11
; total layer number: 142
; total filament length [mm] : 7843.21
; total filament volume [cm^3] : 18866.42
; total filament weight [g] : 23.62
; model printing time: 1h 2m 3s; total estimated time: 1h 5m 10s
; HEADER_BLOCK_END
`

// PrusaSlicer writes its totals and the whole config at the bottom.
const prusaFooter = `; filament used [mm] = 5123.4
; filament used [cm3] = 12.3
; filament used [g] = 15.29
; filament cost = 0.38
; total filament used [g] = 15.29
; estimated printing time (normal mode) = 2h 4m 6s
; estimated printing time (silent mode) = 2h 10m 1s
; prusaslicer_config = begin
; filament_colour = #FF8000
; filament_diameter = 1.75
; filament_type = PETG
; prusaslicer_config = end
`

const curaHeader = `;FLAVOR:Marlin
;TIME:4983
;Filament used: 3.21456m
;Layer height: 0.2
;Generated with Cura_SteamEngine 5.7.1
`

func TestOrcaHeader(t *testing.T) {
	m := ParseGcodeMeta(orcaHeader)
	if m.Grams != 23.62 || m.Length != 7843.21 {
		t.Errorf("grams=%v length=%v", m.Grams, m.Length)
	}
	// The total, not the model-only figure.
	if m.Seconds != 3910 {
		t.Errorf("seconds = %v, want 3910 (1h 5m 10s)", m.Seconds)
	}
	if m.Slicer != "OrcaSlicer" {
		t.Errorf("slicer = %q", m.Slicer)
	}
}

func TestPrusaFooter(t *testing.T) {
	m := ParseGcodeMeta(prusaFooter)
	if m.Grams != 15.29 || m.Material != "PETG" || m.Colour != "#ff8000" {
		t.Errorf("got %+v", m)
	}
	// Normal mode comes first and is the one that wins.
	if m.Seconds != 2*3600+4*60+6 {
		t.Errorf("seconds = %v", m.Seconds)
	}
}

// Cura gives metres and no weight. Grams come from the plastic's density.
func TestCuraLengthBecomesGrams(t *testing.T) {
	m := ParseGcodeMeta(curaHeader)
	if m.Seconds != 4983 || math.Abs(m.Length-3214.56) > 0.01 || m.Grams != 0 {
		t.Fatalf("got %+v", m)
	}
	// 3.21456 m of 1.75 mm PLA at 1.24 g/cm³ is about 9.6 g.
	g := m.GramsFor(1.24)
	if g < 9.5 || g > 9.7 {
		t.Errorf("GramsFor = %.2f, want about 9.6", g)
	}
	if m.Slicer != "Cura" {
		t.Errorf("slicer = %q", m.Slicer)
	}
}

// Two extruders report two figures; the print uses both.
func TestMultiExtruderFiguresAreAdded(t *testing.T) {
	m := ParseGcodeMeta("; filament used [g] = 12.5, 3.5\n; filament_type = PLA;PETG\n")
	if m.Grams != 16 || m.Material != "PLA" {
		t.Errorf("got %+v", m)
	}
}

// A real-sized file: the figures sit at the ends and the middle is moves.
func TestReadGcodeMetaReadsBothEnds(t *testing.T) {
	var b bytes.Buffer
	b.WriteString(orcaHeader)
	for b.Len() < 2<<20 {
		b.WriteString("G1 X100.123 Y100.456 E0.0321 F3000\n")
	}
	b.WriteString(prusaFooter) // a footer too, as if both were present
	data := b.Bytes()

	m := ReadGcodeMeta(bytes.NewReader(data), int64(len(data)))
	if m.Grams != 23.62 { // the header's total wins over the footer's
		t.Errorf("grams = %v", m.Grams)
	}
	if m.Material != "PETG" || m.Colour != "#ff8000" {
		t.Errorf("footer not read: %+v", m)
	}
}

func TestMoveLinesAreNotMistakenForMetadata(t *testing.T) {
	m := ParseGcodeMeta(";LAYER_CHANGE\n;Z:12.2\n;TYPE:External perimeter\n;TIME_ELAPSED:812.3\nG1 X1 Y1\n")
	if m.Known() {
		t.Errorf("body comments read as metadata: %+v", m)
	}
}

// --- colour ---------------------------------------------------------------------

func TestNormaliseHex(t *testing.T) {
	for in, want := range map[string]string{
		"#FF8000": "#ff8000", "ff8000": "#ff8000", "#f80": "#ff8800",
		"#FF8000FF": "#ff8000", "nope": "", "#12345": "", "": "",
	} {
		if got := normaliseHex(in); got != want {
			t.Errorf("normaliseHex(%q) = %q, want %q", in, got, want)
		}
	}
}

func TestColourFamilies(t *testing.T) {
	for hex, want := range map[string]string{
		"#1a1a1a": "black", "#000000": "black", "#ffffff": "white", "#f5f5f2": "white",
		"#8c8f93": "grey", "#c8202f": "red", "#f07c1c": "orange", "#f5c518": "yellow",
		"#2f9e44": "green", "#1f5fbf": "blue", "#69b3e7": "blue", "#6a3fa0": "purple",
		"#ef7fb0": "pink", "#6b4423": "brown", "#178a8a": "blue",
	} {
		if got := ColourFamily(hex); got != want {
			t.Errorf("ColourFamily(%s) = %q, want %q", hex, got, want)
		}
	}
	// Every preset lands in a family that has a filter chip.
	known := map[string]bool{}
	for _, f := range ColourFamilies {
		known[f.Key] = true
	}
	for _, p := range ColourPresets {
		if !known[ColourFamily(p.Hex)] {
			t.Errorf("preset %s (%s) has no chip: %q", p.Name, p.Hex, ColourFamily(p.Hex))
		}
	}
}

// Perceived, not arithmetic: navy is closer to black than to sky blue, which
// plain RGB distance gets backwards often enough to matter.
func TestColourDistanceIsPerceptual(t *testing.T) {
	if ColourDistance("#ff0000", "#ff0000") != 0 {
		t.Error("a colour is no distance from itself")
	}
	if !(ColourDistance("#c8202f", "#d23b3b") < ColourDistance("#c8202f", "#f07c1c")) {
		t.Error("two reds should be closer than red and orange")
	}
	if !math.IsInf(ColourDistance("#ff0000", "nope"), 1) {
		t.Error("an unreadable colour should be infinitely far")
	}
}

// --- slicer material names ---------------------------------------------------------

func TestMaterialFromSlicer(t *testing.T) {
	for in, want := range map[string]string{
		"PLA": "pla", "PLA+": "pla", "PolyTerra PLA": "pla", "Matte PLA": "pla",
		"PETG": "petg", "PCTG": "petg", "PanChroma PETG": "petg", // "PA" inside a brand name
		"PA-CF": "pa-cf", "PAHT-CF": "pa-cf", "PA6-GF": "pa-cf", "PA12": "pa", "Nylon": "pa",
		"TPU": "tpu", "TPU 95A": "tpu", "ABS": "abs", "ASA": "asa", "PC": "pc",
		"PLA-CF": "filled-pla", "Wood PLA": "filled-pla", "PVA": "pva", "PEEK": "peek",
		"": "", "mystery": "",
	} {
		if got := MaterialFromSlicer(in); got != want {
			t.Errorf("MaterialFromSlicer(%q) = %q, want %q", in, got, want)
		}
	}
}

// --- picking a spool ----------------------------------------------------------------

func spoolsForPicking() []Spool {
	n4 := int64(1)
	return []Spool{
		{ID: 1, Material: "petg", ColourName: "Black", ColourHex: "#1a1a1a", NetGrams: 1000, UsedGrams: 100},
		{ID: 2, Material: "petg", ColourName: "Orange", ColourHex: "#f07c1c", NetGrams: 1000, UsedGrams: 600},
		{ID: 3, Material: "petg", ColourName: "Orange", ColourHex: "#ef7f1a", NetGrams: 1000, UsedGrams: 100},
		{ID: 4, Material: "pla", ColourName: "White", ColourHex: "#f5f5f2", NetGrams: 1000, PrinterID: &n4},
	}
}

func TestPickSpoolPrefersWhatIsLoaded(t *testing.T) {
	m := PickSpool(spoolsForPicking(), 1, GcodeMeta{Material: "PLA"})
	if !m.Found || m.Spool.ID != 4 || !strings.Contains(m.Reason, "loaded") {
		t.Errorf("got %+v", m)
	}
}

// Loaded PLA, print sliced for PETG: the loaded spool is the wrong plastic and
// must not be picked just because it is on the printer.
func TestPickSpoolSkipsALoadedSpoolOfTheWrongPlastic(t *testing.T) {
	m := PickSpool(spoolsForPicking(), 1, GcodeMeta{Material: "PETG", Colour: "#FF8000"})
	if !m.Found || m.Spool.Material != "petg" {
		t.Fatalf("got %+v", m)
	}
	// Two oranges, near enough the same: the one with least left goes first.
	if m.Spool.ID != 2 {
		t.Errorf("picked spool %d, want 2 (the orange with least left)", m.Spool.ID)
	}
}

func TestPickSpoolByColour(t *testing.T) {
	m := PickSpool(spoolsForPicking(), 0, GcodeMeta{Material: "PETG", Colour: "#101010"})
	if m.Spool.ID != 1 || !strings.Contains(m.Reason, "colour") {
		t.Errorf("a near-black print should pick the black spool, got %+v", m)
	}
}

func TestPickSpoolFindsNothingRatherThanGuessing(t *testing.T) {
	if m := PickSpool(spoolsForPicking(), 0, GcodeMeta{Material: "ABS"}); m.Found {
		t.Errorf("there is no ABS, got %+v", m)
	}
	if m := PickSpool(spoolsForPicking(), 0, GcodeMeta{}); m.Found {
		t.Errorf("with no material and nothing loaded there is nothing to go on, got %+v", m)
	}
}

// --- spools in the store ------------------------------------------------------------

func TestWeighingASpool(t *testing.T) {
	app := newTestApp(t)
	id, err := app.store.AddSpool(Spool{Material: "petg", ColourHex: "#f07c1c", NetGrams: 1000, TareGrams: 220})
	if err != nil {
		t.Fatal(err)
	}
	got, err := app.store.WeighSpool(id, 632)
	if err != nil {
		t.Fatal(err)
	}
	if got.Remaining() != 412 {
		t.Errorf("632 g on the scale minus a 220 g spool = %v left, want 412", got.Remaining())
	}
	if _, err := app.store.WeighSpool(id, 1400); err == nil {
		t.Error("more than the spool held new should be refused — the tare is probably wrong")
	}

	noTare, _ := app.store.AddSpool(Spool{Material: "pla", NetGrams: 1000})
	if _, err := app.store.WeighSpool(noTare, 800); err == nil || !strings.Contains(err.Error(), "empty spool") {
		t.Errorf("weighing without a tare should say why: %v", err)
	}
}

func TestOneSpoolPerPrinter(t *testing.T) {
	app := newTestApp(t)
	pid, _ := app.store.AddPrinter(Printer{Name: "N4"})
	a, _ := app.store.AddSpool(Spool{Material: "pla", NetGrams: 1000})
	b, _ := app.store.AddSpool(Spool{Material: "petg", NetGrams: 1000})

	app.store.LoadSpool(a, &pid)
	app.store.LoadSpool(b, &pid)
	sa, _ := app.store.GetSpool(a)
	sb, _ := app.store.GetSpool(b)
	if sa.Loaded() || !sb.Loaded() || sb.PrinterName != "N4" {
		t.Errorf("loading b should take a off: a=%v b=%v", sa.Loaded(), sb.Loaded())
	}
	if got, ok := app.store.LoadedSpool(pid); !ok || got.ID != b {
		t.Errorf("LoadedSpool = %v, %v", got.ID, ok)
	}
}

func TestSpoolNeedsAMaterialAndAWeight(t *testing.T) {
	app := newTestApp(t)
	if _, err := app.store.AddSpool(Spool{Material: "unobtainium", NetGrams: 1000}); err == nil {
		t.Error("an unknown material should be refused")
	}
	if _, err := app.store.AddSpool(Spool{Material: "pla"}); err == nil {
		t.Error("a spool with no weight should be refused")
	}
}

func TestDryNotes(t *testing.T) {
	if (Spool{Material: "pla"}).DryNote() != "" {
		t.Error("PLA does not need nagging")
	}
	if !strings.Contains((Spool{Material: "pa"}).DryNote(), "dry it") {
		t.Error("never-dried nylon should say to dry it")
	}
	recent := Spool{Material: "pa", DriedAt: time.Now().Add(-time.Hour)}
	if recent.DryNote() != "" {
		t.Error("nylon dried an hour ago is fine")
	}
	old := Spool{Material: "pa", DriedAt: time.Now().Add(-5 * 24 * time.Hour)}
	if !strings.Contains(old.DryNote(), "5 days") {
		t.Errorf("got %q", old.DryNote())
	}
}

func TestFinishedSpoolsDropOffTheShelfButAreKept(t *testing.T) {
	app := newTestApp(t)
	id, _ := app.store.AddSpool(Spool{Material: "pla", NetGrams: 1000})
	app.store.FinishSpool(id)
	if list, _ := app.store.ListSpools(false); len(list) != 0 {
		t.Error("a used-up spool should leave the shelf")
	}
	if list, _ := app.store.ListSpools(true); len(list) != 1 || !list[0].Empty() || list[0].Remaining() != 0 {
		t.Errorf("but stay on record: %+v", list)
	}
}

// --- a print takes its filament ---------------------------------------------------

func sendOrca(t *testing.T, app *App, printerID int64, fields map[string]string, grams float64, material, colour string) *httptest.ResponseRecorder {
	t.Helper()
	body := fmt.Sprintf(`; HEADER_BLOCK_START
; generated by OrcaSlicer 2.1.1
; total filament weight [g] : %.2f
; model printing time: 1h 0m 0s; total estimated time: 1h 30m 0s
; HEADER_BLOCK_END
G28
G1 Z0.2
; filament_type = %s
; filament_colour = %s
`, grams, material, colour)
	buf, ctype := multipartGcode(t, fields, "case.gcode", body)
	req := httptest.NewRequest(http.MethodPost, fmt.Sprintf("/printing/printers/%d/send", printerID), buf)
	req.Header.Set("Content-Type", ctype)
	rec := httptest.NewRecorder()
	app.routes().ServeHTTP(rec, req)
	return rec
}

func TestPrintTakesItsFilamentOffTheLoadedSpool(t *testing.T) {
	app := newTestApp(t)
	fake := &fakeMoonraker{state: "standby"}
	srv := httptest.NewServer(fake)
	defer srv.Close()
	pid, _ := app.store.AddPrinter(Printer{Name: "Neptune 4", LinkKind: "moonraker", LinkURL: srv.URL})
	sid, _ := app.store.AddSpool(Spool{Material: "petg", ColourName: "Orange", ColourHex: "#f07c1c", NetGrams: 1000})
	app.store.LoadSpool(sid, &pid)

	rec := sendOrca(t, app, pid, map[string]string{"start": "on"}, 23.62, "PETG", "#F07C1C")
	flash, _ := url.QueryUnescape(rec.Header().Get("Location"))
	if !strings.Contains(flash, "24 g from Orange PETG") || strings.Contains(flash, "error=") {
		t.Errorf("redirect = %s", flash)
	}

	sp, _ := app.store.GetSpool(sid)
	if math.Abs(sp.UsedGrams-23.62) > 0.001 {
		t.Errorf("spool used %v, want 23.62", sp.UsedGrams)
	}
	jobs, _ := app.store.PrintJobs(JobFilter{Printer: pid}, 5)
	if len(jobs) != 1 || jobs[0].Grams != 23.62 || jobs[0].EstSeconds != 5400 || jobs[0].SpoolName != "Orange PETG" {
		t.Errorf("job = %+v", jobs[0])
	}
}

// Sliced for PLA, PETG loaded and chosen by hand: it still sends, and says so.
func TestWrongPlasticAndShortSpoolAreFlagged(t *testing.T) {
	app := newTestApp(t)
	srv := httptest.NewServer(&fakeMoonraker{state: "standby"})
	defer srv.Close()
	pid, _ := app.store.AddPrinter(Printer{Name: "N4", LinkKind: "moonraker", LinkURL: srv.URL})
	sid, _ := app.store.AddSpool(Spool{Material: "petg", ColourName: "Black", NetGrams: 1000, UsedGrams: 950})

	rec := sendOrca(t, app, pid, map[string]string{"spool_id": fmt.Sprint(sid)}, 120, "PLA", "#FFFFFF")
	loc, _ := url.QueryUnescape(rec.Header().Get("Location"))
	if !strings.Contains(loc, "sliced for PLA") {
		t.Errorf("should warn about the plastic: %s", loc)
	}
	if !strings.Contains(loc, "needs about 120 g") || !strings.Contains(loc, "50 g left") {
		t.Errorf("should warn about running out: %s", loc)
	}
	if jobs, _ := app.store.PrintJobs(JobFilter{}, 5); len(jobs) != 1 || !jobs[0].OK() {
		t.Error("warnings must not stop the send")
	}
}

func TestDontCountMeansDontCount(t *testing.T) {
	app := newTestApp(t)
	srv := httptest.NewServer(&fakeMoonraker{state: "standby"})
	defer srv.Close()
	pid, _ := app.store.AddPrinter(Printer{Name: "N4", LinkKind: "moonraker", LinkURL: srv.URL})
	sid, _ := app.store.AddSpool(Spool{Material: "pla", NetGrams: 1000})
	app.store.LoadSpool(sid, &pid)

	sendOrca(t, app, pid, map[string]string{"spool_id": "none"}, 40, "PLA", "")
	if sp, _ := app.store.GetSpool(sid); sp.UsedGrams != 0 {
		t.Errorf("\"don't count\" took %v g", sp.UsedGrams)
	}
}

func TestPuttingFilamentBackWorksOnce(t *testing.T) {
	app := newTestApp(t)
	srv := httptest.NewServer(&fakeMoonraker{state: "standby"})
	defer srv.Close()
	pid, _ := app.store.AddPrinter(Printer{Name: "N4", LinkKind: "moonraker", LinkURL: srv.URL})
	sid, _ := app.store.AddSpool(Spool{Material: "pla", NetGrams: 1000})
	app.store.LoadSpool(sid, &pid)
	sendOrca(t, app, pid, map[string]string{"start": "on"}, 40, "PLA", "")

	jobs, _ := app.store.PrintJobs(JobFilter{}, 5)
	ret := func() *httptest.ResponseRecorder {
		rec := httptest.NewRecorder()
		app.routes().ServeHTTP(rec, httptest.NewRequest(http.MethodPost,
			fmt.Sprintf("/printing/jobs/%d/return", jobs[0].ID), nil))
		return rec
	}
	ret()
	if sp, _ := app.store.GetSpool(sid); sp.UsedGrams != 0 {
		t.Errorf("after putting it back the spool used %v", sp.UsedGrams)
	}
	loc, _ := url.QueryUnescape(ret().Header().Get("Location"))
	if !strings.Contains(loc, "error=") {
		t.Error("a second put-back should be refused")
	}
	if sp, _ := app.store.GetSpool(sid); sp.UsedGrams != 0 {
		t.Errorf("a second put-back changed the spool: %v", sp.UsedGrams)
	}
}

// --- print hours and maintenance ------------------------------------------------------

func TestHoursFromSentPrintsAndBaseHours(t *testing.T) {
	app := newTestApp(t)
	srv := httptest.NewServer(&fakeMoonraker{state: "standby"})
	defer srv.Close()
	pid, _ := app.store.AddPrinter(Printer{Name: "N4", LinkKind: "moonraker", LinkURL: srv.URL})
	app.store.SetBaseHours(pid, 100)
	sid, _ := app.store.AddSpool(Spool{Material: "pla", NetGrams: 1000})
	app.store.LoadSpool(sid, &pid)
	sendOrca(t, app, pid, map[string]string{"start": "on"}, 10, "PLA", "") // 1.5 h
	sendOrca(t, app, pid, map[string]string{"start": "on"}, 10, "PLA", "") // 1.5 h

	p, _ := app.store.GetPrinter(pid)
	h, _ := app.store.PrinterHours(p)
	if h.Total != 103 || h.Source != "estimate" {
		t.Errorf("got %+v, want 103 h estimated", h)
	}

	// A print that did not happen no longer counts towards wear.
	jobs, _ := app.store.PrintJobs(JobFilter{}, 5)
	if _, err := app.store.ReturnJobFilament(jobs[0].ID); err != nil {
		t.Fatal(err)
	}
	h, _ = app.store.PrinterHours(p)
	if h.Total != 101.5 {
		t.Errorf("after one is put back: %v, want 101.5", h.Total)
	}
}

// When the printer keeps its own count, that is the number.
func TestHoursFromThePrinterWin(t *testing.T) {
	app := newTestApp(t)
	fake := &fakeMoonraker{state: "standby", totalSeconds: 512 * 3600}
	srv := httptest.NewServer(fake)
	defer srv.Close()
	pid, _ := app.store.AddPrinter(Printer{Name: "N4", LinkKind: "moonraker", LinkURL: srv.URL})

	rec := httptest.NewRecorder()
	app.routes().ServeHTTP(rec, httptest.NewRequest(http.MethodGet, fmt.Sprintf("/printing/printers/%d", pid), nil))
	if !strings.Contains(rec.Body.String(), "512 h") {
		t.Error("the printer page should show the printer's own count")
	}
	// And it was kept, so it is there when the printer is off.
	p, _ := app.store.GetPrinter(pid)
	if h, _ := app.store.PrinterHours(p); h.Total != 512 || h.Source != "printer" {
		t.Errorf("kept hours = %+v", h)
	}
}

func TestMaintenanceStates(t *testing.T) {
	now := time.Date(2026, 10, 12, 12, 0, 0, 0, time.UTC)
	belt := MaintTask{Task: "belts", EveryHours: 100, LastHours: 400, LastAt: now.AddDate(0, 0, -30)}

	if s := belt.State(450, now); s.Due || s.Soon || s.Headline() != "in 50 hours of printing" {
		t.Errorf("half way: %+v %q", s, s.Headline())
	}
	if s := belt.State(495, now); !s.Soon || s.Due {
		t.Errorf("5 h left of 100 should be soon: %+v", s)
	}
	if s := belt.State(512, now); !s.Due || s.Headline() != "overdue by 12 hours" {
		t.Errorf("12 h over: %+v %q", s, s.Headline())
	}

	fans := MaintTask{Task: "fans", EveryDays: 90, LastAt: now.AddDate(0, 0, -91)}
	if s := fans.State(0, now); !s.Due || !strings.HasPrefix(s.Headline(), "overdue by") {
		t.Errorf("91 days into 90: %+v %q", s, s.Headline())
	}
	fans.LastAt = now.AddDate(0, 0, -76)
	if s := fans.State(0, now); s.Headline() != "in 2 weeks" {
		t.Errorf("14 days left reads %q", s.Headline())
	}
}

func TestMaintenanceClockStartsWhenAddedAndResetsWhenDone(t *testing.T) {
	app := newTestApp(t)
	pid, _ := app.store.AddPrinter(Printer{Name: "N4", BaseHours: 300})
	p, _ := app.store.GetPrinter(pid)
	h, _ := app.store.PrinterHours(p)

	id, err := app.store.AddMaint(MaintTask{PrinterID: pid, Task: "Check belt tension", EveryHours: 100}, h.Total)
	if err != nil {
		t.Fatal(err)
	}
	// 300 h on the clock when added: not overdue for the 300 h before.
	tasks, _ := app.store.ListMaint(pid)
	if st := tasks[0].State(h.Total, time.Now()); st.Due {
		t.Error("a task added today should not be due today")
	}

	app.store.SetBaseHours(pid, 420)
	if due := app.store.MaintDue([]Printer{{ID: pid, BaseHours: 420}}); due[pid] != 1 {
		t.Errorf("120 h later it is due: %v", due)
	}

	if _, err := app.store.DoneMaint(id, 420, "snugged up"); err != nil {
		t.Fatal(err)
	}
	if due := app.store.MaintDue([]Printer{{ID: pid, BaseHours: 420}}); due[pid] != 0 {
		t.Error("done should reset the clock")
	}
	app.store.DeleteMaint(id)
	if log, _ := app.store.MaintHistory(pid, 5); len(log) != 1 || log[0].Note != "snugged up" {
		t.Errorf("deleting the task should keep the log: %+v", log)
	}
}

