func TestFilamentFiltersByColour(t *testing.T) {
	app := newTestApp(t)
	app.store.AddSpool(Spool{Material: "petg", ColourName: "Fire Red", ColourHex: "#c8202f", NetGrams: 1000})
	app.store.AddSpool(Spool{Material: "pla", ColourName: "Signal Red", ColourHex: "#d23b3b", NetGrams: 1000})
	app.store.AddSpool(Spool{Material: "pla", ColourName: "Ocean", ColourHex: "#1f5fbf", NetGrams: 1000})

	get := func(q string) string {
		rec := httptest.NewRecorder()
		app.routes().ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/filament"+q, nil))
		return rec.Body.String()
	}
	reds := get("?colour=red")
	if !strings.Contains(reds, "Fire Red") || !strings.Contains(reds, "Signal Red") || strings.Contains(reds, "Ocean PLA") {
		t.Error("?colour=red should show both reds and not the blue")
	}
	redPLA := get("?colour=red&material=pla")
	if strings.Contains(redPLA, "Fire Red PETG") || !strings.Contains(redPLA, "Signal Red PLA") {
		t.Error("red and PLA together should be just the red PLA")
	}
}

func TestAddingSeveralIdenticalSpools(t *testing.T) {
	app := newTestApp(t)
	form := url.Values{"material": {"petg"}, "swatch": {"#1a1a1a"}, "count": {"4"},
		"net_grams": {"1000"}, "tare_grams": {"180"}}
	req := httptest.NewRequest(http.MethodPost, "/filament", strings.NewReader(form.Encode()))
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	app.routes().ServeHTTP(httptest.NewRecorder(), req)

	list, _ := app.store.ListSpools(false)
	if len(list) != 4 {
		t.Fatalf("a box of four should be four spools, got %d", len(list))
	}
	// Picking a swatch names it, so the list does not fill with nameless spools.
	if list[0].ColourName != "Black" || list[0].Label() != "Black PETG" {
		t.Errorf("label = %q", list[0].Label())
	}
}

