func TestThingQRCodes(t *testing.T) {
	app := newTestApp(t)
	for _, path := range []string{"/qr/spool/1", "/qr/board/1", "/qr/machine/1", "/qr/printer/1"} {
		rec := httptest.NewRecorder()
		app.routes().ServeHTTP(rec, httptest.NewRequest(http.MethodGet, path, nil))
		if rec.Code != 200 || !strings.HasPrefix(rec.Header().Get("Content-Type"), "image/png") {
			t.Errorf("%s: %d %s", path, rec.Code, rec.Header().Get("Content-Type"))
		}
	}
	rec := httptest.NewRecorder()
	app.routes().ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/qr/anything/1", nil))
	if rec.Code != http.StatusNotFound {
		t.Errorf("an unknown kind should 404, got %d", rec.Code)
	}
	for _, what := range []string{"spools", "boards", "machines", "printers"} {
		rec := httptest.NewRecorder()
		app.routes().ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/labels/"+what, nil))
		if rec.Code != 200 {
			t.Errorf("/labels/%s: %d", what, rec.Code)
		}
	}
}

