// The print's spool is not the loaded one: the printer is about to run the
// wrong filament, and the person sending it has to hear that.
func TestSendingWithADifferentSpoolThanLoadedWarns(t *testing.T) {
	app := newTestApp(t)
	srv := httptest.NewServer(&fakeMoonraker{state: "standby"})
	defer srv.Close()
	pid, _ := app.store.AddPrinter(Printer{Name: "N4", LinkKind: "moonraker", LinkURL: srv.URL})
	pla, _ := app.store.AddSpool(Spool{Material: "pla", ColourName: "Black", NetGrams: 1000})
	app.store.LoadSpool(pla, &pid)
	app.store.AddSpool(Spool{Material: "petg", ColourName: "Orange", ColourHex: "#f07c1c", NetGrams: 1000})

	rec := sendOrca(t, app, pid, map[string]string{"start": "on"}, 23, "PETG", "#FF8000")
	loc, _ := url.QueryUnescape(rec.Header().Get("Location"))
	if !strings.Contains(loc, "Black PLA is what is loaded on N4, not Orange PETG") {
		t.Errorf("should warn that the wrong spool is loaded: %s", loc)
	}
	if !strings.Contains(loc, "from Orange PETG") {
		t.Errorf("the grams should still come off the PETG it was sliced for: %s", loc)
	}
}

// Sent while the printer was busy, started later from its screen: it still
// wore the printer, so it still counts — the same rule as the filament.
func TestUnstartedSendsCountUntilMarkedNotPrinted(t *testing.T) {
	app := newTestApp(t)
	srv := httptest.NewServer(&fakeMoonraker{state: "printing", busy: true})
	defer srv.Close()
	pid, _ := app.store.AddPrinter(Printer{Name: "N4", LinkKind: "moonraker", LinkURL: srv.URL})
	sendOrca(t, app, pid, map[string]string{"start": "on"}, 10, "PLA", "") // 1.5 h, did not start

	p, _ := app.store.GetPrinter(pid)
	if h, _ := app.store.PrinterHours(p); h.Total != 1.5 {
		t.Errorf("a sent print counts until marked otherwise: %v h", h.Total)
	}

	// No spool was involved, and it can still be marked as never printed.
	jobs, _ := app.store.PrintJobs(JobFilter{}, 5)
	if !jobs[0].CanReturn() || jobs[0].GivesBack() {
		t.Fatalf("a spool-less job should be markable but give nothing back: %+v", jobs[0])
	}
	app.store.ReturnJobFilament(jobs[0].ID)
	if h, _ := app.store.PrinterHours(p); h.Total != 0 {
		t.Errorf("marked not printed, it should stop counting: %v h", h.Total)
	}
}
